/**
 * @distilled.cloud/entire -- Entire SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the two OpenAPI documents mirrored
 * at `specs/spec-mirror-entire/specs/{core,cell}.json`. Everything else in
 * this folder is hand-written.
 *
 * One module per API tag. The Core control plane: `orgs`, `projects`,
 * `repos`, `mirrors`, `nativeMirrors`, `serviceAccounts`, `identity`,
 * `plugins`, `billing`, `clusters`. The regional cell: `trails`,
 * `trailReviews`, `sessions`, `checkpoints`, `repositories` (git),
 * `environments`, `agents`, `runs`, `search`, `brainstore`, ...
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Entire from "@distilled.cloud/entire";
 *
 * const program = Effect.gen(function* () {
 *   const me = yield* Entire.identity.getMe({});
 *   const project = yield* Entire.projects.createProject({
 *     name: "acme",
 *     ownerType: "account",
 *     ownerId: me.global.accountId,
 *   });
 *   const repo = yield* Entire.repos.createRepo({ projectId: project.id, name: "api" });
 *   const { items } = yield* Entire.trails.listTrails({ repo_id: repo.id });
 *   return { repo, trails: items ?? [] };
 * });
 *
 * const Live = Layer.mergeAll(FetchHttpClient.layer, Entire.CredentialsFromEnv);
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  EntireCellProtocol,
  EntireCoreProtocol,
  type EntireOpError,
  type EntireOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
